+
+                // Whether an icon placed in the given cell would be covered by one of the widgets.
+                function cellCoveredByWidget(stripe, pos, widgets) {
+                    const spacing = Kirigami.Units.smallSpacing;
+                    const contentHeight = Math.min(cellHeight, iconSize + (Kirigami.Units.gridUnit * Plasmoid.configuration.textLines) + (spacing * 3));
+                    const origin = cellPosition(stripe, pos);
+                    const icon = contentItem.mapToItem(root.appletsLayout, origin.x + spacing * 2, origin.y + spacing * 2,
+                                                       cellWidth - spacing * 4, contentHeight - spacing * 4);
+                    return widgets.some(widget => icon.x < widget.x + widget.width && widget.x < icon.x + icon.width
+                                                  && icon.y < widget.y + widget.height && widget.y < icon.y + icon.height);
+                }
+
+                function updateBlockedCells() {
+                    const widgets = widgetGeometries();
+                    if (widgets === null) {
+                        // Wait for the drag to end
+                        return;
+                    }
+                    const perStripe = positioner.perStripe;
+                    const cells = [];
+                    if (widgets.length > 0 && !root.useListViewMode) {
+                        for (let s = 0; s < positioner.optimalStripes; s++) {
+                            for (let p = 0; p < perStripe; p++) {
+                                if (cellCoveredByWidget(s, p, widgets)) {
+                                    cells.push((s * perStripe) + p);
+                                }
+                            }
+                        }
+                    }
+                    positioner.blockedCells = cells;
+                    if (widgetsChangedByUser) {
+                        widgetsChangedByUser = false;
+                        moveIconsOutOfWidgets();
+                    }
+                }
+
+                // Moves the icons that a widget was just moved, resized or added over to the nearest free cells.
+                function moveIconsOutOfWidgets() {
+                    if (!positioner.enabled) {
+                        return;
+                    }
+                    const moves = [];
+                    for (const cell of positioner.blockedCells) {
+                        if (cell < positioner.rowCount() && !positioner.isBlank(cell)) {
+                            const to = nearestCellFreeOfWidgets(cell, cell, moves.filter((_, j) => j % 2 === 1));
+                            if (to !== cell) {
+                                moves.push(cell, to);
+                            }
+                        }
+                    }
+                    if (moves.length) {
+                        positioner.move(moves);
+                        // Moving selects the moved icons, but the user didn't pick them
+                        dir.clearSelection();
+                    }
+                }
+
+                // The free cell nearest to the given one that no widget covers.
+                function nearestCellFreeOfWidgets(from, to, taken) {
+                    if (!positioner.isBlocked(to)) {
+                        return to;
+                    }
+                    const perStripe = positioner.perStripe;
+                    const target = cellPosition(Math.floor(to / perStripe), to % perStripe);
+                    const stripes = Math.max(positioner.optimalStripes, Math.ceil(positioner.rowCount() / perStripe));
+                    let best = -1;
+                    let bestDistance = Infinity;
+                    for (let s = 0; s < stripes; s++) {
+                        for (let p = 0; p < perStripe; p++) {
+                            const index = (s * perStripe) + p;
+                            if ((index !== from && !positioner.isBlank(index)) || taken.includes(index) || positioner.isBlocked(index)) {
+                                continue;
+                            }
+                            const point = cellPosition(s, p);
+                            const distance = Math.hypot(point.x - target.x, point.y - target.y);
+                            if (distance < bestDistance) {
+                                best = index;
+                                bestDistance = distance;
+                            }
+                        }
+                    }
+                    // Every cell is taken: let the positioner append it after the last one
+                    return best;
+                }
