+
+void Positioner::setBlockedCells(const QList<int> &cells)
+{
+    QList<int> sortedCells(cells);
+    std::sort(sortedCells.begin(), sortedCells.end());
+    sortedCells.erase(std::unique(sortedCells.begin(), sortedCells.end()), sortedCells.end());
+
+    if (m_blockedCells == sortedCells) {
+        return;
+    }
+
+    // In manual mode items keep their positions, in sorted mode they flow around the new cells
+    const bool reset = !m_enabled && m_folderModel;
+
+    if (reset) {
+        beginResetModel();
+    }
+
+    m_blockedCells = sortedCells;
+
+    if (reset) {
+        endResetModel();
+    }
+
+    Q_EMIT blockedCellsChanged();
+}
+
+bool Positioner::isBlocked(int row) const
+{
+    return std::binary_search(m_blockedCells.cbegin(), m_blockedCells.cend(), row);
+}
