+int Positioner::firstUnblockedRow(int row) const
+{
+    while (isBlocked(row)) {
+        ++row;
+    }
+
+    return row;
+}
+
+bool Positioner::flowsAroundBlockedCells() const
+{
+    return !m_enabled && m_folderModel && !m_blockedCells.isEmpty();
+}
+
+int Positioner::cellForSourceRow(int row) const
+{
+    for (const int cell : std::as_const(m_blockedCells)) {
+        if (cell > row) {
+            break;
+        }
+        ++row;
+    }
+
+    return row;
+}
+
+int Positioner::sourceRowForCell(int cell) const
+{
+    if (isBlocked(cell)) {
+        return -1;
+    }
+
+    const int row = cell - (std::lower_bound(m_blockedCells.cbegin(), m_blockedCells.cend(), cell) - m_blockedCells.cbegin());
+
+    return row < m_folderModel->rowCount() ? row : -1;
+}
